package demo;
import org.springframework.test.context.*;
import org.springframework.test.annotation.DirtiesContext;

// Test-only adapter: one shared dependency lease per JVM, regardless of mode.
// Workspace mode: MultiContainerSupport.acquire() clones private databases from
// the runner-owned warm pool and creates a private topic on the owned broker;
// no containers are started and the warm pool is never stopped by the tests.
// CI modes (per-class-*, suite-parallel): acquire() starts the shared containers
// once and the same code path binds them.
final class LeaseAdapter {
    static void before(TestContext context)throws Exception {
        // Never rewrite the runner-supplied config: workspace mode must stay
        // workspace mode (owned warm leases), CI modes must stay CI (fresh
        // shared containers). acquire() is idempotent per JVM, so the first
        // test class pays the one-time setup and later classes reuse the lease.
        MultiContainerSupport.acquire(context.getTestClass().getSimpleName());
    }
    static void properties(DynamicPropertyRegistry registry) {
        var b=MultiContainerSupport.current;
        int n=b.pg.size();
        registry.add("fixture.databases",()->n);
        for(int i=0;i<n;i++){int index=i;
            registry.add("fixture.pg."+index+".url",()->b.pg.get(index).url());
            registry.add("fixture.pg."+index+".user",()->b.pg.get(index).user());
            registry.add("fixture.pg."+index+".password",()->b.pg.get(index).password());
        }
        registry.add("fixture.kafka",()->b.bootstrap);
        // The leased topic is unique per run (dt-<lease>); never a shared name.
        registry.add("fixture.topic",()->b.topic);
    }
    static void after(TestContext context)throws Exception {
        // Mark the context dirty so Spring closes the producer and JDBC
        // connections before the lease is released; otherwise the drop of the
        // cloned databases can race live connections.
        context.markApplicationContextDirty(DirtiesContext.HierarchyMode.EXHAUSTIVE);
        // Release only when this JVM has finished every selected class (or in
        // per-class mode, after each class). The JVM shutdown hook covers forks
        // that exit early. The warm pool itself is owned by the runner and is
        // never stopped from here.
        if(MultiContainerSupport.config().perClass()||MultiContainerSupport.completed.incrementAndGet()>=MultiContainerSupport.config().classes()){
            MultiContainerSupport.release();
        }
    }
}

