package demo;
import org.springframework.test.context.*;

// Workspace mode: use owned warm leases from fixture_runtime_start.
// CI mode: start fresh containers via MultiContainerSupport.
final class LeaseAdapter {
    static void before(TestContext context) throws Exception {
        var config = MultiContainerSupport.config();
        // Detect workspace mode (owned lease supplied by runner).
        if (config.mode().equals("workspace")) {
            // Reuse the warm dependency leases already allocated for this test class.
            // No container startup, no credential exposure.
            MultiContainerSupport.acquire(context.getTestClass().getSimpleName());
        } else {
            // CI mode: start fresh containers with full configuration.
            MultiContainerSupport.config = new MultiContainerSupport.Config(
                config.run(), "per-class-sequential",
                config.databases(), config.classes(), config.parallelism(),
                config.timeoutSeconds(), config.postgresImage(), config.kafkaImage(),
                config.bindings()
            );
            MultiContainerSupport.acquire(context.getTestClass().getSimpleName());
        }
    }

    static void properties(org.springframework.test.context.DynamicPropertyRegistry registry) {
        var b = MultiContainerSupport.current;
        // Workspace mode: bind fixture.databases and fixture.pg.N.* from the warm lease.
        // CI mode: same bindings, but containers are freshly started.
        if (b != null) {
            registry.add("fixture.databases", () -> 1);
            for (var pg : b.pg) {
                registry.add("fixture.pg.0.url", () -> pg.url());
                registry.add("fixture.pg.0.user", () -> pg.user());
                registry.add("fixture.pg.0.password", () -> pg.password());
            }
            registry.add("fixture.kafka", () -> b.bootstrap);
            registry.add("fixture.topic", () -> "quotes");
        }
    }

    static void after(TestContext context) throws Exception {
        // Close the context once after all classes in a test class run.
        // This applies to both workspace and CI modes.
        MultiContainerSupport.closeContext.run();
        if (!MultiContainerSupport.config().mode().equals("workspace")) {
            // CI mode: release owned containers.
            MultiContainerSupport.release();
        }
    }
}
